#define main prototype_original_main
#include "workload.c"
#undef main
#include "shared_transition.c.inc"
#include <errno.h>

typedef struct ScreenPoint {
  Stats counters;
  size_t peak_rss_bytes;
  uint64_t boehm_collection_number;
} ScreenPoint;
typedef struct ScreenReport {
  double construction, initial_major, churn, validation, final_major, cleanup;
  ScreenPoint before_churn, after_churn, after_final;
} ScreenReport;
static ScreenPoint screen_point(void) {
  struct rusage r; int status=getrusage(RUSAGE_SELF,&r);assert(status==0);
#ifdef __APPLE__
  size_t rss=(size_t)r.ru_maxrss;
#else
  size_t rss=(size_t)r.ru_maxrss*1024;
#endif
  uint64_t collections=0;
#ifdef USE_BOEHM
  collections=(uint64_t)GC_get_gc_no();
#endif
  return (ScreenPoint){stats,rss,collections};
}
static uint64_t exact_tree(Word node,size_t count,uint64_t base) {
  if (!count) {assert(node==0);return 0;}
  assert(node && !(node&1));size_t left=count/2,right=count-left-1;
  uint64_t id=base+count-1;assert(load(node,0)==integer(id));
  return unbox(load(node,0))+exact_tree(load(node,1),left,base)
      +exact_tree(load(node,2),right,base+left);
}
static uint64_t screen_tree(size_t count,ScreenReport *report) {
  Word head=0,anchor=0;Root h,a;uint64_t id=0;
  double t=now();root_push(&h,&head);root_push(&a,&anchor);
  head=tree(count,&id);report->construction=now()-t;
  t=now();uint64_t checksum=exact_tree(head,count,0);report->validation=now()-t;
  assert(id==count && checksum==(uint64_t)count*(count-1)/2);
  report->before_churn=screen_point();report->after_churn=report->before_churn;
  observed=checksum;t=now();major_collect();report->final_major=now()-t;
  report->after_final=screen_point();t=now();
  assert(exact_tree(head,count,0)==checksum);
#ifndef USE_BOEHM
  assert(stats.old_object_count==count && stats.old_live_bytes==count*32);
#endif
  head=anchor=0;root_pop(&a);root_pop(&h);report->cleanup=now()-t;return checksum;
}
static uint64_t screen_young_or_stable(int stable,size_t count,size_t churn,ScreenReport *report) {
  Word graph=0,node=0;Root g,n;root_push(&g,&graph);root_push(&n,&node);
  uint64_t total=0,id=0;double t=now();
  if (stable) graph=tree(count,&id);
  report->construction=now()-t;
  if (stable) {
    t=now();major_collect();report->initial_major=now()-t;
    t=now();total=exact_tree(graph,count,0);report->validation=now()-t;
    assert(id==count && total==(uint64_t)count*(count-1)/2);
  }
  report->before_churn=screen_point();t=now();
