      "\"requests\":%zu,\"checksum\":%" PRIu64 ",\"elapsed_seconds\":%.9f,"
      "\"preparation_seconds\":%.9f,\"construction_seconds\":%.9f,\"initial_major_seconds\":%.9f,"
      "\"churn_seconds\":%.9f,\"validation_seconds\":%.9f,\"final_major_seconds\":%.9f,"
      "\"cleanup_seconds\":%.9f,\"harness_fixed_bytes\":%zu,",
      profile,count,churn,window,capacity,requests,checksum,elapsed,prep,report.construction,
      report.initial_major,report.churn,report.validation,report.final_major,report.cleanup,
      sizeof report+sizeof transition+sizeof layouts);
