        "\"transition_after_churn_pool_reserved_bytes\":%zu,\"transition_churn_major_count\":%" PRIu64,
        transition.before_drop.old_live_bytes,transition.after_churn.old_live_bytes,
        transition.after_churn.pool_reserved_bytes,transition.after_churn.major_count-transition.before_drop.major_count);
