  GcLayout old = prepare_layout(capacity / sizeof(Word) + 1, 2);
  Word child = 0, parent = 0; Root rc, rp;
  root_push(&rc, &child); root_push(&rp, &parent);
  child = make(cell); put(cell, child, 0, integer(29));
  parent = make(old);
