    expected += bytes(layouts[i].words);
  }
  REQUIRE(stats.old_live_bytes == expected, "prepared descriptor growth exact liveness");
  for (size_t i = SHAPES; i-- > 0;) { slots[i] = 0; root_pop(&roots[i]); }
