  root_pop(&rc); empty(); heap_destroy();
}

enum { GRAPH_N = 2000, GRAPH_ROOTS = 32 };
static unsigned edges[GRAPH_N + 1][2], ids[GRAPH_ROOTS], seen[GRAPH_N + 1];
