  Large **link = &large_objects;
  while (*link) {
    Large *l = *link; Header *h = &l->object;
    if (h->info & MARKED) { h->info &= ~(uintptr_t)MARKED; link = &l->next; }
    else {
      reclaim(h); *link = l->next;
