  size_t window=positive(argv[4]),capacity=positive(argv[5]);
  if (count>=1000000000 || churn>=1000000000 || capacity<32 || capacity>SIZE_MAX/4
      || (uint64_t)count+churn+(count+63)/64>=1000000000) {
