#define REQUIRE(test, message) do { if (!(test)) { \
  fprintf(stderr, "pressure control: %s\n", message); abort(); \
} } while (0)

static void charge_identity(void) {
#if PRESSURE_ENABLED
  REQUIRE(pressure.charged_bytes + gc_fast.used == stats.payload_bytes + stats.allocation_header_bytes,
