  REQUIRE(stats.old_live_bytes == 0 && stats.old_object_count == 0, "empty final live oracle");
  REQUIRE(stats.pool_reserved_bytes == 0 && stats.large_reserved_bytes == 0, "empty final reservation");
  charge_identity(); heap_destroy();
}
static void seed_four(Word values[4], Root roots[4]) {
  heap_init(240);
  for (size_t i=0;i<4;++i) {
    root_push(&roots[i], &values[i]);
    values[i]=allocate(3,2); store(values[i],0,integer(i+1)); store(values[i],2,integer(i+100));
  }
  major_collect();
  REQUIRE(stats.old_live_bytes == 128 && stats.old_object_count == 4, "seed exact live oracle");
  REQUIRE(gc_fast.old_limit == 1216, "seed unchanged old limit");
#if PRESSURE_ENABLED
  REQUIRE(pressure.debt == 0 && pressure.budget == 1216 && pressure.major_count == 0,
          "seed major reset and budget");
