  ((Word *)object)[index] = value;
#ifndef GC_MUTATE_BARRIER
  if (!young && is_young(value) && !(h->info & REMEMBERED)) {
    h->info |= REMEMBERED; queue_push(&remembered, h, &stats.remembered_queue_bytes);
  }
#else
  (void)young;
#endif
}
void heap_destroy(void) {
