#include <assert.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

Stats stats;
GcFastState gc_fast;
uintptr_t gc_heap_epoch;

#ifdef USE_BOEHM
#include <gc/gc.h>
void *prototype_inline_alloc(long long bytes);
size_t prototype_inline_root_bytes(void);
int prototype_inline_enabled(void);
