static void scan_promote(Header *h) {
  Descriptor d = *descriptor(h); Word *fields = (Word *)(h + 1);
  for (size_t i = 0; i < d.words && i < 64; ++i)
    if ((d.mask >> i) & 1) fields[i] = promote(fields[i]);
