         stats.promoted_count, stats.reclaimed_bytes, stats.old_live_bytes, stats.peak_old_bytes,
         stats.peak_accounted_bytes, gc_fast.used, stats.old_total_allocated_bytes, stats.peak_root_bytes, stats.old_live_bytes,
