/* Independent request-derived pacing oracle, correctness only.
   Include frozen candidate unchanged so arithmetic helpers can be tested too. */
#include "gc.c"

static void require(int condition, const char *message) {
  if (!condition) { fprintf(stderr, "independent pressure assertion: %s\n", message); exit(1); }
}
static Word chain(size_t count, GcLayout layout, Word *slot) {
  for (size_t i = 0; i < count; ++i) {
    Word node = (i & 1) ? allocate(3, 2) : allocate_prepared(layout);
    store_prepared(layout, node, 0, integer(i));
    store_prepared(layout, node, 1, *slot);
    *slot = node;
  }
  return *slot;
}
static void check_chain(Word node, size_t count) {
  while (count) {
    require(unbox(load(node, 0)) == count - 1, "retained chain ordinals");
    node = load(node, 1); --count;
  }
  require(node == 0, "retained chain terminator");
}
static void request_dead(size_t bytes, int prepared) {
  size_t words = bytes / 8 - 1;
  Word node = prepared ? allocate_prepared(prepare_layout(words, 0)) : allocate(words, 0);
  require(load(node, 0) == 0, "new allocation remains zeroed");
  store(node, 0, integer(bytes));
}

static void exhaustion(void) {
  heap_init(257); GcLayout layout = prepare_layout(3, 2);
  Word graph = 0; Root root; root_push(&root, &graph); chain(5, layout, &graph);
  major_collect(); check_chain(graph, 5);
  uint64_t promoted = stats.promoted_count; graph = 0;
  /* 5*32 old bytes => budget 2*160+4*257=1348. Each exhausted
     nursery contributes 8*32=256, so boundary6 occurs at request49. */
  for (size_t request = 1; request <= 120; ++request) {
    request_dead(32, request & 1);
    require(stats.major_count == (request < 49 ? 1u : 2u), "exhaustion first event at request49, no empty-old majors");
    require(stats.old_live_bytes == (request < 49 ? 160u : 0u), "zero-promotion graph drop bound");
    require(stats.promoted_count == promoted, "all churn dies young");
  }
  root_pop(&root); heap_destroy();
}

static void retained_anchor(void) {
  heap_init(257); GcLayout layout = prepare_layout(3, 2);
  Word nodes[5] = {0}; Root roots_local[5];
  for (size_t i = 0; i < 5; ++i) {
    root_push(&roots_local[i], &nodes[i]); nodes[i] = allocate_prepared(layout);
    store_prepared(layout, nodes[i], 0, integer(100 + i));
  }
  for (size_t i = 0; i < 4; ++i) store_prepared(layout, nodes[i], 1, nodes[(i + 1) % 4]);
  major_collect();
  size_t logical_debt = 0, logical_live = 160, budget = 1348;
  uint64_t expected_major = 1;
  for (size_t i = 0; i < 180; ++i) {
    if (i == 45) for (size_t j = 0; j < 4; ++j) nodes[j] = 0;
    size_t request_bytes = 16 + (i % 4) * 16;
    request_dead(request_bytes, i & 1); logical_debt += request_bytes;
    if (logical_debt >= budget) {
      ++expected_major; logical_debt = 0;
      if (i >= 45) logical_live = 32;
      budget = 2 * logical_live + 4 * 257;
    }
    minor_collect();
    require(stats.major_count == expected_major, "heterogeneous manual-minor request schedule");
    require(stats.old_live_bytes == logical_live, "retained cycle then exact permanent anchor");
    require(unbox(load(nodes[4], 0)) == 104 && load(nodes[4], 1) == 0, "permanent anchor data");
    if (i < 45) for (size_t j = 0; j < 4; ++j) {
      require(unbox(load(nodes[j], 0)) == 100 + j, "retained cyclic graph data");
      require(load(nodes[j], 1) == nodes[(j + 1) % 4], "retained cyclic graph edges");
    }
  }
  for (size_t i = 5; i-- > 0;) root_pop(&roots_local[i]);
  heap_destroy();
}

static void direct_old(void) {
  heap_init(257); GcLayout layout = prepare_layout(3, 2), large = prepare_layout(32, 1);
  Word graph = 0, first = 0, second = 0; Root rg, rf, rs;
  root_push(&rg, &graph); chain(3, layout, &graph); major_collect();
  /* L96 => budget1220. 31 forced 32-byte requests charge992.
     A 264-byte direct-old request crosses the budget AFTER returning;
     the following request must collect BEFORE making its new object. */
  for (size_t i = 0; i < 31; ++i) { request_dead(32, i & 1); minor_collect(); }
  require(stats.major_count == 1, "direct-old setup remains below request budget");
  root_push(&rf, &first); first = allocate_prepared(large);
  require(stats.major_count == 1 && stats.old_live_bytes == 360, "direct-old return is created before any later pressure event");
  store_prepared(large, first, 0, graph); store_prepared(large, first, 31, integer(731));
  root_push(&rs, &second); second = allocate(32, 1);
  require(stats.major_count == 2 && stats.old_live_bytes == 624 && stats.old_object_count == 5,
          "direct-old pressure happens before new unrooted return creation");
  require(load(second, 0) == 0 && load(second, 31) == 0, "new direct-old payload valid and zeroed");
  require(load(first, 0) == graph && unbox(load(first, 31)) == 731, "previous direct-old root preserved");
  check_chain(graph, 3);
  root_pop(&rs); root_pop(&rf); root_pop(&rg); heap_destroy();
}

static void reset_epoch(void) {
  heap_init(257); GcLayout layout = prepare_layout(3, 2);
  Word graph = 0; Root root; root_push(&root, &graph); chain(4, layout, &graph); major_collect();
  for (size_t i = 0; i < 38; ++i) { request_dead(32, i & 1); minor_collect(); }
  request_dead(32, 1); major_collect();
  require(stats.major_count == 2 && stats.old_live_bytes == 128, "explicit major performs one prepass and one sweep");
  /* The preceding1216 flushed +32 pending bytes cannot survive reset.
     Fresh budget1284 requires41 new32-byte minor boundaries. */
  for (size_t i = 1; i <= 41; ++i) {
    request_dead(32, i & 1); minor_collect();
    require(stats.major_count == (i < 41 ? 2u : 3u), "explicit major resets full pressure epoch");
    check_chain(graph, 4);
  }
  uintptr_t epoch = gc_heap_epoch; root_pop(&root); heap_destroy();
  heap_init(257); require(gc_heap_epoch != epoch, "heap epoch advances");
  for (size_t i = 0; i < 100; ++i) { request_dead(32, i & 1); minor_collect(); }
  require(stats.major_count == 0 && stats.old_live_bytes == 0, "empty-old epochs discard pressure");
  layout = prepare_layout(3, 2); graph = 0; root_push(&root, &graph); chain(1, layout, &graph); minor_collect();
  /* Initial budget1028; promotion boundary charges32, so request32 is
     the first subsequent forced minor to exceed it (1056 bytes). */
  for (size_t i = 1; i <= 32; ++i) {
    request_dead(32, i & 1); minor_collect();
    require(stats.major_count == (i < 32 ? 0u : 1u), "new heap has independent initial budget and no old debt");
    check_chain(graph, 1);
  }
  root_pop(&root); heap_destroy();
}

static void arithmetic(void) {
  const size_t amounts[] = {0, 1, 32, 257, SIZE_MAX / 2, SIZE_MAX};
  for (size_t i = 0; i < sizeof amounts / sizeof amounts[0]; ++i) {
    size_t amount = amounts[i];
    require(pressure_add(0, amount) == amount, "zero-debt addition");
    require(pressure_add(SIZE_MAX - amount, amount) == SIZE_MAX, "exact maximal debt addition");
    if (amount) require(pressure_add(SIZE_MAX - amount + 1, amount) == SIZE_MAX,
                        "debt addition saturates instead of wrapping");
  }
  const size_t capacities[] = {32, 257, SIZE_MAX / 4};
  for (size_t i = 0; i < sizeof capacities / sizeof capacities[0]; ++i) {
    size_t reserve = capacities[i] * 4, largest = (SIZE_MAX - reserve) / 2;
    require(pressure_budget_for(0, capacities[i]) == reserve, "empty-heap budget is exact reserve");
    require(pressure_budget_for(largest, capacities[i]) == largest * 2 + reserve,
            "largest representable unsaturated budget");
    require(pressure_budget_for(largest + 1, capacities[i]) == SIZE_MAX,
            "budget saturates at first overflowing live count");
    require(pressure_budget_for(SIZE_MAX, capacities[i]) == SIZE_MAX,
            "maximal synthetic live count saturates");
  }
  heap_init(257);
  require(static_metadata_bytes() >= sizeof(PressureState) + sizeof(Stats) + sizeof(GcFastState),
          "pacing state participates in static memory accounting");
  require(stats.peak_accounted_bytes == accounted_bytes(), "initial peak includes pacing metadata");
  heap_destroy();
}

int main(int argc, char **argv) {
  require(argc == 2, "one grouped case required");
  if (!strcmp(argv[1], "exhaustion")) exhaustion();
  else if (!strcmp(argv[1], "retained-anchor")) retained_anchor();
  else if (!strcmp(argv[1], "direct-old")) direct_old();
  else if (!strcmp(argv[1], "reset-epoch")) reset_epoch();
  else if (!strcmp(argv[1], "arithmetic")) arithmetic();
  else { require(0, "unknown grouped case"); }
  printf("independent pressure passed: %s\n", argv[1]); return 0;
}

